import sim, random
qs=[q for q in sim.load() if q['topic'] in ('combinatorics','number_theory')]
for thr in (0.2,0.3,0.4):
  for cap in (4,5,6,8,10):
    acc=0;use=0;N=0
    for seed in range(20):
        rng=random.Random(seed)
        for q in qs:
            pools={v:list(q['pools'][v]) for v in range(5)}
            for p in pools.values(): rng.shuffle(p)
            best=None;bs=-9;u=0
            for j in range(cap):
                p=pools[j%5]
                if not p:
                    allp=[x for v in pools for x in pools[v]]
                    if not allp: break
                    a,s=allp[rng.randrange(len(allp))]
                else: a,s=p.pop()
                u+=1
                if s>bs: best,bs=a,s
                if s>=thr: break
            acc+=(best==q['correct']); use+=u; N+=1
    print(f'thr={thr} cap={cap}: acc={acc/N:.3f} use={use/N:.2f}')
"
